                "title": "연습용 그림과 빨간 건물 그리기 함수 준비하기",
                "body": [
                  "<p>산불·숲 그림을 만들고, 산불이 아닌 <code>make_red_building()</code> 함수도 준비해요. 빨간 건물은 학습 데이터에 한 장도 들어 있지 않아요.</p>"
                ],
                "code": {
                  "lang": "python",
                  "src": "import numpy as np\nimport matplotlib.pyplot as plt\n\n# 연습용 '가짜 사진' 만들기: 진짜 산불 사진 대신 규칙과 난수로 32x32 컬러 그림을 만들어요\nnp.random.seed(7)                     # 언제 실행해도 같은 그림이 나오도록 고정\nH = W = 32\nyy, xx = np.mgrid[0:H, 0:W] / (H - 1)   # 0~1 사이 좌표\n\ndef make_fire():                      # 산불 그림: 어두운 연기 배경 + 밝은 주황빛 불꽃 덩어리\n    img = np.zeros((H, W, 3)) + np.random.uniform(0.08, 0.25)\n    heat = np.zeros((H, W))\n    for _ in range(np.random.randint(2, 5)):\n        cx, cy = np.random.uniform(0.15, 0.85), np.random.uniform(0.5, 0.95)\n        sx, sy = np.random.uniform(0.06, 0.15), np.random.uniform(0.15, 0.35)\n        heat += np.exp(-((xx - cx) ** 2 / (2 * sx ** 2) + (yy - cy) ** 2 / (2 * sy ** 2)))\n    heat = np.clip(heat + np.random.normal(0, 0.08, (H, W)), 0, 1)\n    img[:, :, 0] += 1.0 * heat           # R(빨강)\n    img[:, :, 1] += 0.75 * heat ** 1.5   # G(초록)\n    img[:, :, 2] += 0.25 * heat ** 3     # B(파랑)\n    return (np.clip(img, 0, 1) * 255).astype(np.uint8)\n\ndef make_forest():                    # 산불이 아닌 그림: 초록 숲 (절반은 위쪽에 하늘)\n    base = [np.random.uniform(0.08, 0.25), np.random.uniform(0.35, 0.6), np.random.uniform(0.08, 0.25)]\n    img = np.zeros((H, W, 3)) + base\n    img += np.random.normal(0, 0.06, (H, W, 1)) * np.array([0.6, 1.0, 0.6])\n    if np.random.rand() < 0.5:\n        sky = int(np.random.uniform(0.15, 0.4) * H)\n        img[:sky] = np.array([0.55, 0.75, 0.95]) + np.random.normal(0, 0.03, (sky, W, 3))\n    return (np.clip(img, 0, 1) * 255).astype(np.uint8)\n\ntrain_fire = [make_fire() for _ in range(162)]        # 'fire' 폴더 역할\ntrain_non_fire = [make_forest() for _ in range(162)]  # 'non' 폴더 역할\nimages = np.array(train_fire + train_non_fire)\nlabels = np.array([0] * 162 + [1] * 162)              # 0 = 산불(fire), 1 = 산불 아님(non)\ndef make_red_building():              # 빨간색 건물 그림 (산불이 아님!)\n    img = np.zeros((H, W, 3)) + [0.55, 0.75, 0.95]   # 하늘\n    img[6:, 4:28] = [0.72, 0.16, 0.12]                # 빨간 벽돌 벽\n    for r in range(9, 30, 6):\n        for c in range(7, 26, 6):\n            img[r:r + 3, c:c + 3] = [0.12, 0.12, 0.15]    # 창문\n    img += np.random.normal(0, 0.02, img.shape)\n    return (np.clip(img, 0, 1) * 255).astype(np.uint8)\nprint('연습용 이미지:', images.shape)",
                  "run": true
                }
